#include <algorithm>
#include <cmath>
#include <cstring>
#include <fstream>
#include <iostream>
#include <string>
#include <vector>
#include <net.h>

namespace {
bool load(const std::string& path, std::vector<float>& x, size_t size) { x.resize(size); std::ifstream f(path, std::ios::binary); f.read((char*)x.data(), (std::streamsize)(size * sizeof(float))); return f && f.gcount() == (std::streamsize)(size * sizeof(float)); }
bool compare(const char* label, const std::vector<float>& actual, const std::vector<float>& expected) { if(actual.size()!=expected.size()) return false; float maximum=0.f; double total=0.; size_t nan=0, inf=0; for(size_t i=0;i<actual.size();++i){if(std::isnan(actual[i]))++nan;if(std::isinf(actual[i]))++inf;float e=std::fabs(actual[i]-expected[i]);maximum=std::max(maximum,e);total+=e;}std::cout<<label<<" max_abs_error="<<maximum<<" mean_abs_error="<<total/actual.size()<<" nan_count="<<nan<<" inf_count="<<inf<<"\n";return maximum<1e-4f&&nan==0&&inf==0;}
std::vector<float> reverse(const std::vector<float>& windows) { std::vector<float> output(1*4*8*8*32); for(int window=0;window<4;++window){int hb=window/2, wb=window%2;for(int token=0;token<64;++token){int t=token/16,h=(token/4)%4,w=token%4;for(int c=0;c<32;++c)output[((((t*8+(hb*4+h))*8+(wb*4+w))*32)+c)]=windows[((window*64+token)*32)+c];}}return output;}
}
int main(int argc,char**argv){if(argc!=2){std::cerr<<"usage: ncnn_full_fidelity_runner <artifact_dir>\n";return 2;}std::string r=argv[1];std::vector<float>windows,mask,cos,sin,expected_windows,expected_output;if(!load(r+"/windows.bin",windows,4*64*32)||!load(r+"/reference_mask.bin",mask,4*64*64)||!load(r+"/reference_rope_cos.bin",cos,64*4)||!load(r+"/reference_rope_sin.bin",sin,64*4)||!load(r+"/reference_windows.bin",expected_windows,4*64*32)||!load(r+"/reference_output.bin",expected_output,1*4*8*8*32))return 3;ncnn::Net net;net.opt.use_vulkan_compute=false;net.opt.use_packing_layout=false;net.opt.num_threads=1;if(net.load_param((r+"/model.ncnn.param").c_str())||net.load_model((r+"/model.ncnn.bin").c_str()))return 4;ncnn::Mat in0(32,64,4),in1(64,64,4),in2(4,64),in3(4,64);std::memcpy(in0.data,windows.data(),windows.size()*4);std::memcpy(in1.data,mask.data(),mask.size()*4);std::memcpy(in2.data,cos.data(),cos.size()*4);std::memcpy(in3.data,sin.data(),sin.size()*4);auto ex=net.create_extractor();ncnn::Mat out,checkpoint;int r0=ex.input("in0",in0),r1=ex.input("in1",in1),r2=ex.input("in2",in2),r3=ex.input("in3",in3);const bool perhead=r.find("perhead")!=std::string::npos;int concat=ex.extract(perhead?"296":"87",checkpoint),flatten=ex.extract(perhead?"296":"89",checkpoint),projection=ex.extract(perhead?"297":"90",checkpoint),re=ex.extract("out0",out);std::cerr<<"input_rets="<<r0<<","<<r1<<","<<r2<<","<<r3<<" concat="<<concat<<" flatten="<<flatten<<" output_gemm="<<projection<<" extract_ret="<<re<<"\n";if(r0||r1||r2||r3||re)return 5;if(out.total()!=expected_windows.size())return 6;std::vector<float> actual(out.total());std::memcpy(actual.data(),out.data,actual.size()*4);bool pass=compare("core_windows",actual,expected_windows)&&compare("reverse_bthwc",reverse(actual),expected_output);std::cout<<"ncnn_full_fidelity_runner="<<(pass?"PASS":"FAIL")<<"\n";return pass?0:1;}
